package org.viridexa.api.workbench;

import java.util.*;
import java.nio.charset.StandardCharsets;
import java.math.BigDecimal;
import java.security.MessageDigest;
import org.springframework.stereotype.Service;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import org.viridexa.api.plant.PlantService;
import org.viridexa.api.science.*;
import org.viridexa.api.graph.*;
import org.viridexa.api.graph.GraphContract.SourceReference;
import static org.viridexa.api.workbench.WorkbenchContract.*;

@Service @Transactional(readOnly=true,timeout=10)
public class WorkbenchService {
 public static final String PUBLIC_NOTICE="仅展示获准公开的目录、来源与来源测量记录；公开展示不表示已经人工核验；缺失值不等于0，未关联样本不代表已识别物种。";
 public static final String CANDIDATE_NOTICE="未经人工核验，仅供候选数据审查，不构成正式科学结论。";
 private static final Set<String> KINDS=Set.of("OIL_CONTENT","OIL_FA_COMPOSITION","FAME_COMPOSITION","FOOD_NUTRIENT","FATTY_ACID","OTHER");
 private final WorkbenchRepository repository;private final PlantService plants;private final ScientificService science;private final GraphService graph;private final ComparabilityEngine engine;
 public WorkbenchService(WorkbenchRepository repository,PlantService plants,ScientificService science,GraphService graph,ComparabilityEngine engine){this.repository=repository;this.plants=plants;this.science=science;this.graph=graph;this.engine=engine;}
 public Overview overview(){return overview(false);}
 @PreAuthorize("hasRole('ADMIN')") public Overview adminOverview(){return overview(true);}
 private Overview overview(boolean admin){return new Overview(scope(admin),science.coverage().stream().mapToLong(ScientificService.Coverage::factCount).sum(),repository.visibleSamples(admin),repository.unlinked(admin),stats(repository.states(admin)),stats(repository.kinds(admin)),stats(repository.sourceStats(admin)),notice(admin));}
 private List<Stat> stats(List<Map<String,Object>> rows){return rows.stream().map(r->new Stat(text(r,"stat_key"),text(r,"label"),number(r,"records"))).toList();}
 public List<Plant> plants(String q,int limit){return plantSearch(false,q,limit);}
 @PreAuthorize("hasRole('ADMIN')") public List<Plant> adminPlants(String q,int limit){return plantSearch(true,q,limit);}
 private List<Plant> plantSearch(boolean admin,String q,int limit){limit(limit,20);q=term(q,120);if(admin)return repository.plantSearch(q,limit).stream().map(r->new Plant(number(r,"id"),text(r,"scientific_name"),text(r,"name_zh"),text(r,"identity_state"),text(r,"publication_state"))).toList();return plants.search(q,limit).items().stream().map(p->new Plant(p.id(),p.scientificName(),p.nameZh(),"APPROVED".equals(p.recordStatus())?"VERIFIED":"SOURCE_REPORTED","METADATA_ONLY")).toList();}
 public Map<String,Object> plant(long id){return plant(false,id);}
 @PreAuthorize("hasRole('ADMIN')") public Map<String,Object> adminPlant(long id){return plant(true,id);}
 private Map<String,Object> plant(boolean admin,long id){if(id<1)throw bad("植物标识无效");var node=admin?graph.adminDetail("plant:"+id):graph.detail("plant:"+id);Plant plant;if(admin){var matches=repository.plant(id).stream().findFirst();if(matches.isEmpty())throw missing();var r=matches.get();plant=new Plant(id,text(r,"scientific_name"),text(r,"name_zh"),text(r,"identity_state"),node.publicationState());}else{var p=plants.getById(id);plant=new Plant(id,p.scientificName(),p.nameZh(),"APPROVED".equals(p.recordStatus())?"VERIFIED":"SOURCE_REPORTED",node.publicationState());}return Map.of("plant",plant,"graphNodeId",node.id(),"sources",node.sourceReference(),"notice",notice(admin));}
 public Page<Sample> samples(WorkbenchRepository.Filters filters,int limit,String cursor){return samples(false,filters,limit,cursor);}
 @PreAuthorize("hasRole('ADMIN')") public Page<Sample> adminSamples(WorkbenchRepository.Filters filters,int limit,String cursor){return samples(true,filters,limit,cursor);}
 private Page<Sample> samples(boolean admin,WorkbenchRepository.Filters f,int size,String cursor){limit(size,50);f=validateFilters(f);String ctx=scope(admin)+"|samples|"+f+"|"+size;var rows=repository.samples(admin,f,after(cursor,ctx),size+1);boolean more=rows.size()>size;var items=rows.stream().limit(size).map(r->sample(admin,r)).toList();return new Page<>(items,more?cursor(ctx,items.getLast().id()):null,more,size,scope(admin),notice(admin));}
 private Sample sample(boolean admin,Map<String,Object> row){String id=text(row,"id");boolean course=id.startsWith("course-sample:");return new Sample(id,text(row,"sample_key"),text(row,"study_key"),safeText(text(row,"label")),nullableLong(row.get("plant_id")),text(row,"taxon_id"),text(row,"identity_state"),safeText(text(row,"plant_part")),assayMethod(text(row,"method")),text(row,"linkage_state"),admin?"OBSERVATION_SPECIFIC":"SOURCE_PUBLIC",course?"LEGACY_REVIEW_REQUIRED":"OBSERVATION_SPECIFIC",number(row,"measurement_count"),sources(text(row,"source_id"),Map.of()));}
 public Page<Point> points(List<String> ids,String kind,int limit,String cursor){return points(false,ids,kind,limit,cursor);}
 @PreAuthorize("hasRole('ADMIN')") public Page<Point> adminPoints(List<String> ids,String kind,int limit,String cursor){return points(true,ids,kind,limit,cursor);}
 private Page<Point> points(boolean admin,List<String> ids,String kind,int size,String cursor){limit(size,60);ids=sampleIds(ids);kind=kind(kind);if(!admin)for(String id:ids)if(!id.startsWith("sample:")||!repository.visibleSample(id))throw missing();String ctx=scope(admin)+"|points|"+ids+"|"+kind+"|"+size;var rows=repository.points(admin,ids,kind,after(cursor,ctx),size+1);boolean more=rows.size()>size;var points=rows.stream().limit(size).map(this::point).toList();return new Page<>(points,more?cursor(ctx,points.getLast().id()):null,more,size,scope(admin),notice(admin));}
 private Point point(Map<String,Object> row){var normalized=PublicScientificData.object(row.get("normalized_payload"));String part=first(text(row,"plant_part"),str(normalized.get("plant_part")),str(normalized.get("plantPart")));String recordedMethod=first(text(row,"method"),str(normalized.get("measurement_method")),str(normalized.get("method")));var loc=new LinkedHashMap<>(locator(row.get("locator")));String paperMethod=safeText(str(PublicScientificData.object(normalized.get("paper")).get("method")));if(paperMethod!=null){loc.put("source_method_note",paperMethod);loc.put("method_scope","PAPER_LEVEL_NOT_A_MEASUREMENT_METHOD");}if(recordedMethod!=null&&assayMethod(recordedMethod)==null)loc.put("transcription_method",safeText(recordedMethod));return new Point(text(row,"id"),text(row,"sample_id"),nullableLong(row.get("plant_id")),text(row,"taxon_id"),text(row,"identity_state"),safeText(part),text(row,"kind"),safeText(text(row,"analyte")),safeText(text(row,"raw_value")),decimal(row.get("value_numeric")),text(row,"unit"),safeText(text(row,"basis")),assayMethod(recordedMethod),text(row,"review_state"),text(row,"publication_state"),text(row,"knowledge_confidence"),text(row,"source_id"),text(row,"license_state"),text(row,"integrity_state"),loc,text(row,"id"));}
 public Evidence evidence(String id){return evidence(false,id);}
 @PreAuthorize("hasRole('ADMIN')") public Evidence adminEvidence(String id){return evidence(true,id);}
 private Evidence evidence(boolean admin,String id){Point point=load(admin,id);List<SourceReference> refs=new ArrayList<>(sources(point.sourceId(),point.locator()));List<Map<String,Object>> lineage;if(!admin&&id.startsWith("candidate:")){lineage=new ArrayList<>(science.lineage(id.substring(10)));lineage.addAll(science.documents(id.substring(10)));lineage=PublicScientificData.rows(lineage);}else{var node=admin?graph.adminDetail(id):graph.detail(id);lineage=new ArrayList<>(List.of(Map.of("nodeId",node.id(),"verificationState",node.verificationState(),"publicationState",node.publicationState(),"sourceReferences",node.sourceReference())));if(admin&&id.startsWith("candidate:")){var documents=graph.adminNeighbors(id,"SUPPORTED_BY","SOURCE",null,20,null,1);for(var edge:documents.edges()){lineage.add(Map.of("relationId",edge.id(),"relationType",edge.relationType(),"from",edge.source(),"to",edge.target(),"sourceReferences",edge.sourceReference()));refs.addAll(edge.sourceReference());}if(documents.hasMore())lineage.add(Map.of("hasMore",true,"nextCursor",documents.nextCursor(),"graphNodeId",id));}}String availability=!refs.isEmpty()&&refs.stream().allMatch(ref->"PERMITTED".equals(ref.licenseState()))&&"VERIFIED".equals(point.sourceIntegrity())?"METADATA_WITH_LICENSED_LINEAGE":"METADATA_ONLY_NO_PUBLIC_ORIGINAL";return new Evidence(point,refs,lineage,availability,admin&&id.startsWith("candidate:")?"/review?candidateId="+id.substring(10):null);}
 public Comparison compare(Selection selection){return compare(false,selection);}
 @PreAuthorize("hasRole('ADMIN')") public Comparison adminCompare(Selection selection){return compare(true,selection);}
 private Comparison compare(boolean admin,Selection selection){if(selection==null||selection.pointIds()==null||selection.pointIds().size()<2||selection.pointIds().size()>12||new HashSet<>(selection.pointIds()).size()!=selection.pointIds().size())throw bad("选择2–12条不同测量记录");var points=selection.pointIds().stream().map(id->load(admin,id)).toList();return engine.check(points);}
 private Point load(boolean admin,String id){pointId(id);var row=repository.point(admin,id);if(row==null)throw missing();return point(row);}
 public Map<String,Object> validateAgentContext(AgentContext context){if(context==null)return Map.of();var clean=new LinkedHashMap<String,Object>();if(context.plantId()!=null){plant(false,context.plantId());clean.put("plantId",context.plantId());}if(context.sampleIds()!=null&&!context.sampleIds().isEmpty()){var ids=sampleIds(context.sampleIds());for(String id:ids)if(!id.startsWith("sample:")||!repository.visibleSample(id))throw missing();clean.put("sampleIds",ids);}if(context.sourceId()!=null&&!context.sourceId().isBlank()){String source=sourceId(context.sourceId());graph.detail(source.startsWith("file:")?source:"source:"+source);clean.put("sourceId",source);}if(context.kind()!=null)clean.put("kind",kind(context.kind()));if(context.plantPart()!=null)clean.put("plantPart",term(context.plantPart(),120));return Collections.unmodifiableMap(clean);}
 private WorkbenchRepository.Filters validateFilters(WorkbenchRepository.Filters f){if(f==null)throw bad("查询参数缺失");if(f.plantId()!=null&&f.plantId()<1)throw bad("植物标识无效");String status=term(f.status(),40);if(status!=null&&!Set.of("PENDING","HELD","APPROVED","REJECTED","NEEDS_EVIDENCE","REVOKED","LEGACY_REVIEW_REQUIRED").contains(status))throw bad("未知审核状态");return new WorkbenchRepository.Filters(term(f.q(),120),f.plantId(),sourceId(f.sourceId()),kind(f.kind()),term(f.plantPart(),120),status,f.unlinked());}
 public static List<String> sampleIds(List<String> values){if(values==null||values.isEmpty()||values.size()>4||new HashSet<>(values).size()!=values.size())throw bad("选择1–4个不同样本");for(String id:values)if(id==null||!id.matches("(?:sample:[0-9a-f]{64}|course-sample:[1-9][0-9]{0,18})"))throw bad("样本标识无效");for(String id:values)boundedNumeric(id);return values.stream().sorted().toList();}
 public static void pointId(String id){if(id==null||!id.matches("(?:candidate:[0-9a-f]{64}|course-measurement:[1-9][0-9]{0,18})"))throw bad("测量标识无效");boundedNumeric(id);}
 private static String sourceId(String id){id=term(id,80);if(id!=null&&!id.matches("(?:[0-9a-f]{64}|file:[1-9][0-9]{0,18})"))throw bad("来源标识无效");if(id!=null)boundedNumeric(id);return id;}
 private static void boundedNumeric(String id){if(id.startsWith("course-")||id.startsWith("file:"))try{Long.parseLong(id.substring(id.indexOf(':')+1));}catch(NumberFormatException e){throw bad("数值标识超出范围");}}
 private static String kind(String kind){kind=term(kind,40);if(kind!=null&&!KINDS.contains(kind))throw bad("未知测量类型");return kind;}
 private List<SourceReference> sources(String source,Map<String,Object> loc){return repository.source(source).stream().map(r->new SourceReference(text(r,"id"),text(r,"label"),text(r,"sha256"),safeText(text(r,"version")),text(r,"license_state"),loc)).toList();}
 private static String scope(boolean a){return a?"ADMIN":"PUBLIC";}private static String notice(boolean a){return a?CANDIDATE_NOTICE:PUBLIC_NOTICE;}
 private static void limit(int n,int max){if(n<1||n>max)throw bad("分页数量超出允许范围");}
 private static String term(String value,int max){if(value==null||value.isBlank())return null;if(value.length()>max||value.chars().anyMatch(Character::isISOControl))throw bad("筛选文本过长或含控制字符");return value.trim();}
 private static Map<String,Object> locator(Object value){return PublicScientificData.object(PublicScientificData.rows(List.of(Map.of("locator",value==null?Map.of():value))).getFirst().get("locator"));}
 private static String assayMethod(String v){return v==null||v.isBlank()||v.toLowerCase(Locale.ROOT).matches(".*(visual_|transcription|page_render).*")?null:safeText(v);}
 private static String safeText(String v){if(v==null)return null;return v.contains("/Users/")||v.contains("/home/")||v.startsWith("/app/")||v.matches("^[A-Za-z]:[\\\\/].*")?null:v.substring(0,Math.min(v.length(),2000));}
 private static String first(String... values){for(String v:values)if(v!=null&&!v.isBlank()&&!v.equals("null"))return v;return null;}
 private static String str(Object o){return o==null?null:o.toString();}private static String text(Map<String,Object> r,String k){return str(r.get(k));}private static long number(Map<String,Object> r,String k){return r.get(k) instanceof Number n?n.longValue():0;}private static Long nullableLong(Object v){return v==null?null:Long.valueOf(v.toString());}private static BigDecimal decimal(Object v){return v==null?null:new BigDecimal(v.toString());}
 private static ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}private static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"记录不存在或当前不可公开");}
 private static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 static String cursor(String context,String last){return Base64.getUrlEncoder().withoutPadding().encodeToString((hash(context)+"\n"+last).getBytes(StandardCharsets.UTF_8));}
 static String after(String cursor,String context){if(cursor==null||cursor.isBlank())return "";try{if(cursor.length()>700)throw bad("游标过长");var parts=new String(Base64.getUrlDecoder().decode(cursor),StandardCharsets.UTF_8).split("\n",-1);if(parts.length!=2||!parts[0].equals(hash(context))||parts[1].length()>180)throw bad("游标不属于当前查询");return parts[1];}catch(IllegalArgumentException e){throw bad("游标格式无效");}}
}
